    # Normalize a dictionary of values to [0,1]
    def normalize(d):
        vals = list(d.values())
        mn, mx = min(vals), max(vals)
        if abs(mx - mn) < 1e-12:
            return {k: 0.5 for k in d}
        return {k: (v - mn)/(mx - mn) for k,v in d.items()}

    eig_n = normalize(eig)
    bc_n = normalize(bc)
    clust_inv = {k: 1 - v for k,v in clust.items()}
    clust_inv_n = normalize(clust_inv)
    core_n = {k: core[k]/max_core_k if max_core_k > 0 else 0.0 for k in core}
    degree_n = normalize(degree)

    # Maintain a static set of already removed nodes' vectors in global attribute for diversity
    removed_nodes = graph.graph.setdefault('removed_nodes', set())
    removed_eig = graph.graph.setdefault('removed_eig', {})

    # Calculate diversity penalty: for each candidate node, measure min eigenvector similarity to removed nodes
    # Similarity = dot product since eigenvector centralities are scalar here, use abs diff as distance
    def diversity_penalty(n):
        if not removed_nodes:
            return 1.0  # no penalty if no nodes removed yet
        n_val = eig_n[n]
        diffs = [abs(n_val - removed_eig[rn]) for rn in removed_nodes if rn in removed_eig]
        if not diffs:
            return 1.0
        return min(diffs)

    # Adaptive weights
    w_eig = 0.4 * bridge_ratio_high_bc + 0.2
    w_bc = 0.3 * bridge_ratio_high_bc + 0.2
    w_clust = 0.3 * (1 - bridge_ratio_high_bc) + 0.1
