            w_core * core_n[n]
        )
        # Incorporate diversity penalty multiplicatively to prioritize structurally novel nodes
        scores[n] = score * div_pen

    next_node = max(scores, key=scores.get)

    # Update removed nodes info for next iteration
    removed_nodes.add(next_node)
    removed_eig[next_node] = eig_n[next_node]

    return next_node

