    min_e, max_e = min(e_vals), max(e_vals)
    if max_e - min_e < 1e-12:
        eigen_norm = {k: 0.0 for k in unvisited_nodes}
    else:
        eigen_norm = {k: (v - min_e) / (max_e - min_e) for k, v in eigenvector.items()}

    # Inverse clustering coefficient normalized
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    inv_clust = {n: 1 - clustering[n] for n in unvisited_nodes}
    c_vals = list(inv_clust.values())
    min_c, max_c = min(c_vals), max(c_vals)
    if max_c - min_c < 1e-12:
        inv_clust_norm = {k: 0.0 for k in unvisited_nodes}
    else:
        inv_clust_norm = {k: (v - min_c) / (max_c - min_c) for k, v in inv_clust.items()}

    # Normalize core number scaled by max_core_k
    core = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}
    if max_core_k > 0:
        core_norm = {n: core[n] / max_core_k for n in unvisited_nodes}
    else:
        core_norm = {n: 0.0 for n in unvisited_nodes}

    # Dynamic weighting factors balancing betweenness and core number by global bridge ratio and degree variance
    w_betw = min(0.7, max(0.3, bridge_ratio_high_bc * 1.5))
    w_core = min(0.7, max(0.1, degree_variance * 0.15))
    # Normalize weights so sum <= 1 for additive scoring, reserve rest for eigenvector and inverse clustering
    w_sum = w_betw + w_core
    w_remain = max(0.0, 1.0 - w_sum)
    w_eigen = w_remain * 0.6
    w_inv_clust = w_remain * 0.4

    scores = {}
    for n in unvisited_nodes:
        score = (
            w_betw * betw_norm[n]
            + w_core * core_norm[n]
            + w_eigen * eigen_norm[n]
            + w_inv_clust * inv_clust_norm[n]
        )
        scores[n] = score

    next_node = max(scores, key=scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph['precomputed']
    apl = pre['apl_lcc']  # average path length in largest connected component

    nodes = unvisited_nodes

    eigenvector = {n: graph.nodes[n]['eigenvector'] for n in nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in nodes}
    core_num = {n: graph.nodes[n]['core_number'] for n in nodes}

    def normalize(d):
        vals = list(d.values())
        min_v, max_v = min(vals), max(vals)
        if max_v - min_v < 1e-12:
            return {k: 0 for k in d}
        return {k: (v - min_v) / (max_v - min_v) for k, v in d.items()}

    eig_n = normalize(eigenvector)
    clust_n = normalize(clustering)
    core_n = normalize(core_num)

    # Weight scheme:
    # Higher apl means network is more spread out; emphasize eigenvector and inverse clustering.
    # Lower apl means more compact; emphasize inverse core number to break dense cores.
    w_eig = 0.5 * (apl / (apl + 1)) + 0.1
    w_clust = 0.4 * (apl / (apl + 1)) + 0.1
    w_core = 0.6 * (1 - apl / (apl + 1)) + 0.1

    scores = {}
    for n in nodes:
        score = (
            w_eig * eig_n[n] +
            w_clust * (1 - clust_n[n]) -
            w_core * core_n[n]
        )
        scores[n] = score

    next_node = max(scores, key=scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph.get('precomputed', {})
    max_core_k = pre.get('max_core_k', 1)
    max_betweenness = max((graph.nodes[n]['betweenness'] for n in unvisited_nodes), default=1)
    min_betweenness = min((graph.nodes[n]['betweenness'] for n in unvisited_nodes), default=0)

    if max_betweenness - min_betweenness < 1e-12:
        bet_norm = {n: 0.5 for n in unvisited_nodes}
    else:
        bet_norm = {n: (graph.nodes[n]['betweenness'] - min_betweenness) / (max_betweenness - min_betweenness) for n in unvisited_nodes}

    next_node = None
    max_score = float('-inf')

    for node in unvisited_nodes:
        core = graph.nodes[node]['core_number'] / max_core_k if max_core_k > 0 else 0
        clustering = graph.nodes[node]['clustering']
        bet = bet_norm[node]

        # Score = (betweenness + core number) weighted positively - clustering penalized
        score = (0.7 * bet + 0.3 * core) * (1 - clustering)

        if score > max_score:
            max_score = score
            next_node = node

    return next_node

