    degree_variance = pre.get('degree_variance', 1)

    # Features for novelty: degree, betweenness, clustering, core_number
    def node_feat(n):
        return (
            graph.nodes[n]['degree'],
            graph.nodes[n]['betweenness'],
            graph.nodes[n]['clustering'],
            graph.nodes[n]['core_number']
        )

    removed_feats = [node_feat(n) for n in removed_nodes] if removed_nodes else []

    def euclidean(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b)) ** 0.5

    novelty_scores = []
    for n in unvisited_nodes:
        f = node_feat(n)
        if removed_feats:
            dist = min(euclidean(f, rf) for rf in removed_feats)
            novelty_scores.append(dist)
        else:
            novelty_scores.append(1.0)

    min_nov, max_nov = min(novelty_scores), max(novelty_scores)
    if max_nov - min_nov < 1e-12:
        novelty_norm = [1.0] * len(novelty_scores)
    else:
        novelty_norm = [(v - min_nov) / (max_nov - min_nov) for v in novelty_scores]

    next_node = None
    max_score = float('-inf')

    for i, n in enumerate(unvisited_nodes):
        deg = graph.nodes[n]['degree']
        betw = graph.nodes[n]['betweenness']

        # Harmonic mean of degree and betweenness centrality
        if deg + betw > 0:
            harm_mean = 2 * deg * betw / (deg + betw)
        else:
            harm_mean = 0

        # Scale score by novelty factor (1 + novelty_norm)
        score = harm_mean * (1 + novelty_norm[i])

        if score > max_score:
            max_score = score
            next_node = n

    return next_node

def select_next_node(graph, unvisited_nodes):
