    # Extract feature lists
    betws = [graph.nodes[n]['betweenness'] for n in unvisited_nodes]
    clusts = [graph.nodes[n]['clustering'] for n in unvisited_nodes]

    # Normalize betweenness
    min_b, max_b = min(betws), max(betws)
    if max_b - min_b < 1e-12:
        betw_norm = [1.0]*len(betws)
    else:
        betw_norm = [(b - min_b) / (max_b - min_b) for b in betws]

    # Normalize clustering and invert (so low clustering preferred)
    min_c, max_c = min(clusts), max(clusts)
    if max_c - min_c < 1e-12:
        inv_clust_norm = [1.0]*len(clusts)
    else:
        clust_norm = [(c - min_c) / (max_c - min_c) for c in clusts]
        inv_clust_norm = [1 - c for c in clust_norm]

    # Harmonic mean helper (to balance both features)
    def harmonic_mean(a, b):
        if a + b == 0:
            return 0
        return 2 * a * b / (a + b)

    best_score = float('-inf')
    next_node = None

    for i, n in enumerate(unvisited_nodes):
        score = harmonic_mean(betw_norm[i], inv_clust_norm[i])
        if score > best_score:
            best_score = score
            next_node = n

    return next_node

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph.get('precomputed', {})
    bridge_ratio = pre.get('bridge_ratio_high_bc', 0.5)
    removed_nodes = pre.get('removed_nodes', set())

    # Feature extractor for core_number and eigenvector (2D vector for diversity)
    def node_feat(n):
        return (graph.nodes[n]['core_number'], graph.nodes[n]['eigenvector'])

    removed_feats = [node_feat(n) for n in removed_nodes] if removed_nodes else []

    def manhattan(a, b):
        return abs(a[0]-b[0]) + abs(a[1]-b[1])

    diversity_scores = []
    for n in unvisited_nodes:
        f = node_feat(n)
        if removed_feats:
            dist = sum(manhattan(f, rf) for rf in removed_feats)/len(removed_feats)
            diversity = dist
        else:
            diversity = 1.0
        diversity_scores.append(diversity)

    min_div, max_div = min(diversity_scores), max(diversity_scores)
    if max_div - min_div < 1e-12:
        diversity_norm = [1.0]*len(diversity_scores)
    else:
        diversity_norm = [(v - min_div)/(max_div - min_div) for v in diversity_scores]

    best_score = float('-inf')
    next_node = None

    for i, n in enumerate(unvisited_nodes):
        betw = graph.nodes[n]['betweenness']
        clust = graph.nodes[n]['clustering']
        # Avoid division by zero, add small epsilon
        frag_score = betw / (clust + 1e-6)

        # Combine fragmentation with diversity weighted by bridge_ratio
        score = frag_score * (1 + bridge_ratio * diversity_norm[i])

        if score > best_score:
            best_score = score
            next_node = n

    return next_node

def select_next_node(graph, unvisited_nodes):
