    else:
        closeness_norm = {n: (closeness_dict[n] - min_c) / (max_c - min_c) for n in unvisited_nodes}

    # Normalize inverse clustering and eigenvector centrality for unvisited nodes
    clusts = [graph.nodes[n]['clustering'] for n in unvisited_nodes]
