        # Penalty proportional to normalized closeness centrality (higher closeness -> lower score)
        penalty = closeness_norm[n]

        # Score combines harmonic mean weighted by (1 - bridge_ratio), minus penalty weighted by bridge_ratio
        score = harm_mean * (1 - bridge_ratio) - penalty * bridge_ratio

