import networkx as nx

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph.get('precomputed', {})
    removed_nodes = pre.get('removed_nodes', set())
    bridge_ratio = pre.get('bridge_ratio_high_bc', 0.5)

    # Cache attributes for efficiency
    degree = {n: graph.nodes[n]['degree'] for n in unvisited_nodes}
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    core = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}
    betw = {n: graph.nodes[n]['betweenness'] for n in unvisited_nodes}
    eig = {n: graph.nodes[n]['eigenvector'] for n in unvisited_nodes}

    # Normalize helper
    def normalize(vals):
        mn, mx = min(vals), max(vals)
        if mx - mn < 1e-12:
            return {k:0.5 for k in vals}
        return {k: (v - mn) / (mx - mn) for k,v in vals.items()}

    deg_n = normalize(degree)
    clust_n = normalize(clustering)
    core_n = normalize(core)
    betw_n = normalize(betw)
    eig_n = normalize(eig)

    # Precompute shortest paths from removed nodes to unvisited nodes (set empty if none removed)
    # To control complexity, we approximate by intersecting sets of neighbors at distance 1 or 2
    # If no removed nodes, diversity penalty is zero
    if not removed_nodes:
        diversity_penalty = {n: 0.0 for n in unvisited_nodes}
    else:
        diversity_penalty = {}
        # For efficiency, precompute neighbors and 2-hop neighbors for removed nodes
        removed_neighbors = set()
        removed_2hop = set()
        for r in removed_nodes:
            nbrs = set(graph.neighbors(r))
            removed_neighbors.update(nbrs)
            for nbr in nbrs:
                removed_2hop.update(graph.neighbors(nbr))
        removed_2hop.difference_update(removed_neighbors)
        removed_2hop.difference_update(removed_nodes)

        for n in unvisited_nodes:
            # count overlap with removed nodes' immediate and secondary neighborhood
            overlap_1 = 1 if n in removed_neighbors else 0
            overlap_2 = 1 if n in removed_2hop else 0
            diversity_penalty[n] = (overlap_1 * 0.7 + overlap_2 * 0.3)

    # Calculate eccentricity within ego-2 subgraph for each unvisited node (normalized)
    # Ego-2 subgraph: node + neighbors + neighbors of neighbors
    eccentricities = {}
    for n in unvisited_nodes:
        ego2 = nx.ego_graph(graph, n, radius=2)
        try:
            ecc = nx.eccentricity(ego2, v=n)
        except nx.NetworkXError:
            ecc = 2  # max distance radius
        eccentricities[n] = ecc

    ecc_n = normalize(eccentricities)

    best_score = float('-inf')
    next_node = None

    for n in unvisited_nodes:
        # Peripheral impact preference (high eccentricity)
        periph = ecc_n[n]

        # Structural importance proxy combining normalized core, betweenness and eigenvector
        struct_imp = (core_n[n] + betw_n[n] + eig_n[n]) / 3

        # Diversity penalty (avoid nodes overlapping removed nodes' neighborhoods)
        div_pen = diversity_penalty[n]

        # Composite score: peripheral * (1 - bridge_ratio) + structural importance * bridge_ratio - diversity penalty
        score = periph * (1 - bridge_ratio) + struct_imp * bridge_ratio - div_pen

        if score > best_score:
            best_score = score
            next_node = n

    return next_node
